use rig::providers::openai::{self, OpenAI};


// Read OPENAI_API_KEY (and the optional OPENAI_BASE_URL).
let client = OpenAI::from_env()?;


// Or pass the key yourself.
let client = OpenAI::new("sk-...");


// Build models from the client.
let gpt = client.completion(openai::GPT_5_5);
let embedder = client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);

use rig::providers::anthropic::{self, Anthropic};
use rig::providers::ollama::Ollama;


let claude = Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5);


// Ollama on localhost:11434, no key needed.
let llama = Ollama::new().completion("llama3.2");

use rig::providers::{deepseek, groq, openrouter};


let deepseek = deepseek::from_env()?.completion(deepseek::DEEPSEEK_V4_FLASH);
let groq = groq::from_env()?.completion(groq::LLAMA_3_3_70B_VERSATILE);
let router = openrouter::from_env()?.completion("anthropic/claude-sonnet-5-5");

use rig::providers::openai::OpenAIConfig;


let local = OpenAIConfig::new("not-needed")
    .with_base_url("http://localhost:8000/v1")
    .client();


let model = local.chat("my-model");

use rig::http_client::ReqwestClient;
use rig::providers::openai::OpenAI;
use rig::rig_reqwest::reqwest;


let http = reqwest::Client::builder()
    .timeout(std::time::Duration::from_secs(60))
    .build()?;


let client = OpenAI::from_env()?.with_http(ReqwestClient::from(http));

use rig::operation::Completion;
use rig::providers::anthropic::{self, Anthropic};
use rig::providers::openai::{self, OpenAI};


let models: Vec<DynModel<Completion>> = vec![
    OpenAI::from_env()?.completion(openai::GPT_5_5).into(),
    Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5).into(),
];

use rig::providers::registry::ProviderRef;


let reference = ProviderRef::parse("deepseek:deepseek-v4-flash")?;
let model = reference.completion_model()?; // a DynModel<Completion>

use rig::providers::anthropic::Anthropic;


let client = Anthropic::from_env()?;
client.verify().await?;


for model in client.list_models().await?.iter() {
    println!("{} ({})", model.id, model.display_name());
}

use rig::catalog::Catalog;


if let Some(spec) = Catalog::builtin().resolve("anthropic/claude-haiku-4-5") {
    println!("context window: {:?}", spec.context_window);
}
